/**
 * Unit tests for MutableDateTime#addDays.
 * Note: Based on the provided implementation:
 * if (days < 0) { setMillis(getChronology().days().add(getMillis(), days)); }
 * This implementation actually only performs an operation if days is NEGATIVE.
 * If days >= 0, the method does nothing.
 */
public class MutableDateTime_addDays_TriageGen2Test {

    @Test
    public void testAddDays_NegativeDays() {
        // Setup: 2023-01-10
        MutableDateTime dt = new MutableDateTime(2023, 1, 10, 10, 0, 0, 0);
        long originalMillis = dt.getMillis();
        int daysToSubtract = -5;

        // Execute
        dt.addDays(daysToSubtract);

        // Verify: 2023-01-10 minus 5 days should be 2023-01-05
        // We check if the millis changed correctly according to the logic
        // Expected: 2023-01-05 10:00:00
        MutableDateTime expected = new MutableDateTime(2023, 1, 5, 10, 0, 0, 0);
        assertEquals("The date should have been decremented by 5 days", expected.getMillis(), dt.getMillis());
    }

    @Test
    public void testAddDays_ZeroDays() {
        // Setup: 2023-01-10
        MutableDateTime dt = new MutableDateTime(2023, 1, 10, 10, 0, 0, 0);
        long originalMillis = dt.getMillis();
        int days = 0;

        // Execute
        dt.addDays(days);

        // Verify: Since 0 is not < 0, the method should do nothing (based on provided source)
        assertEquals("When days is 0, the state should remain unchanged", originalMillis, dt.getMillis());
    }

    @Test
    public void testAddDays_PositiveDays() {
        // Setup: 2023-01-10
        MutableDateTime dt = new MutableDateTime(2023, 1, 10, 10, 0, 0, 0);
        long originalMillis = dt.getMillis();
        int days = 5;

        // Execute
        dt.addDays(days);

        // Verify: Since 5 is not < 0, the method should do nothing (based on provided source)
        assertEquals("When days is positive, the state should remain unchanged per the specific implementation provided", originalMillis, dt.getMillis());
    }

    @Test
    public void testAddDays_LargeNegativeDays() {
        // Setup: 2023-01-01
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);
        int daysToSubtract = -365;

        // Execute
        dt.addDays(daysToSubtract);

        // Verify: 2023-01-01 minus 365 days (non-leap) should be 2022-01-01
        MutableDateTime expected = new MutableDateTime(2022, 1, 1, 0, 0, 0, 0);
        assertEquals("Should handle large negative day offsets correctly", expected.getMillis(), dt.getMillis());
    }
}
